Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

long long gcd_calc(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, n;
    cin >> a >> b >> n;
    int num = 0, den = 1;
    double min_diff = 1e9;

    for (int j = 1; j <= n; ++j) {
        int low_i = (j * a) / b - 1;
        int high_i = (j * a) / b + 1;
        for (int i = low_i; i <= high_i; ++i) {
            double diff = fabs((double)i / j - (double)a / b);
            if (diff < min_diff) {
                min_diff = diff;
                num = i;
                den = j;
            }
        }
    }
    int g = gcd_calc(abs(num), den);
    cout << num / g << "/" << den / g;
}
